static PyObject *run(PyObject *self, PyObject *args) {
    unsigned long long sp, rp, vp, ip, wp, lp, ipp, idxp, datap;
    int n, nrows;
    if (!PyArg_ParseTuple(args, "KKK i KKK KKK i",
                          &sp, &rp, &vp, &n, &ip, &wp, &lp,
                          &ipp, &idxp, &datap, &nrows))
        return NULL;
    ar_state *st = (ar_state *)(uintptr_t)sp;
    double *resid = (double *)(uintptr_t)rp;
    double *v = (double *)(uintptr_t)vp;
    int *ipntr = (int *)(uintptr_t)ip;
    double *workd = (double *)(uintptr_t)wp;
    double *workl = (double *)(uintptr_t)lp;
    const int *indptr = (const int *)(uintptr_t)ipp;
    const int *indices = (const int *)(uintptr_t)idxp;
    const double *data = (const double *)(uintptr_t)datap;

    int steps = 0;
    const int MAX = 2000000;
    ARNAUD_dnaupd(st, resid, v, n, ipntr, workd, workl);
    steps++;
    while (st->ido != 99 && steps < MAX) {
        int ido = st->ido;
        int x0 = ipntr[0];
        int y0 = ipntr[1];
        double *x = workd + x0;
        double *y = workd + y0;
        if (ido == 2) {
            for (int i = 0; i < n; i++) y[i] = x[i];
        } else {
            for (int i = 0; i < nrows; i++) {
                double s = 0.0;
                int a = indptr[i];
                int b = indptr[i + 1];
                for (int j = a; j < b; j++)
                    s += data[j] * x[indices[j]];
                y[i] = s;
            }
        }
        ARNAUD_dnaupd(st, resid, v, n, ipntr, workd, workl);
        steps++;
    }
    return Py_BuildValue("iii", st->info, st->nconv, steps);
}

static PyMethodDef methods[] = {
    {"run", run, METH_VARARGS, "ARPACK reverse-communication loop with CSR matvec"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "arloop", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_arloop(void) { return PyModule_Create(&moduledef); }
